// ── EDIT THE PROMPT HERE ─────────────────────────────────────────────
// The backend posts { query, articles, gemini_key, model }.
// articles: [{title, summary, source_name, source_kind, published, url}]
// (public news content only — no case data crosses to the provider).
const body = $json.body || $json;
const query = body.query || '';
const articles = (body.articles || []).map((a, i) => ({
  n: i + 1, title: a.title, summary: a.summary,
  source: a.source_name, kind: a.source_kind, date: a.published, url: a.url
}));

const SYSTEM = `You are an OSINT analyst assistant for a law-enforcement tool.
You are given NEWS ARTICLES retrieved for the search term "${query}".
Grounded ONLY in these articles (never invent, never use outside knowledge), produce:
1) summary: a concise intelligence summary of what the sources report about the term (2-6 sentences, written in the language of the search term).
2) entities: investigation-relevant named entities mentioned in the articles. For each: {entity_type, label, context, source_url, confidence}. entity_type MUST be one of: person, organization, username, email, phone, location, btc_address, eth_address, domain, url, telegram_user, onion_service, other. label = the value itself (the name / handle / address / place). context = a short phrase on why it matters. source_url = the url of the article it came from. confidence between 0 and 1.
3) connections: plausible relationships BETWEEN the extracted entities, or between an entity and the search term. Each: {from_label, to_label, relation, rationale, confidence}. Use the entity labels EXACTLY as in entities; for the search term use its literal text.
4) case_suggestions: short actionable suggestions of what an investigator should add to the case and why (array of strings).
Omit anything the articles do not support. Do not output markdown. Respond ONLY as JSON with this exact shape:
{"summary":"","entities":[{"entity_type":"","label":"","context":"","source_url":"","confidence":0}],"connections":[{"from_label":"","to_label":"","relation":"","rationale":"","confidence":0}],"case_suggestions":[]}`;

const prompt = SYSTEM + `\n\nARTICLES:\n` + JSON.stringify(articles, null, 1);

const geminiBody = {
  contents: [{ parts: [{ text: prompt }] }],
  generationConfig: { responseMimeType: "application/json", temperature: 0.2 }
};

return [{ json: {
  query: query,
  model: body.model || "gemini-2.0-flash",
  gemini_key: body.gemini_key || "",
  gemini_body: geminiBody
} }];

// Gemini returns candidates[0].content.parts[0].text = the JSON string.
// On an API error (quota/404/…) it returns { error: {...} } — surface it.
const r = $json;
if (r && r.error) {
  return [{ json: { error: 'Gemini: ' + (r.error.message || JSON.stringify(r.error)), code: r.error.code } }];
}
let text = '';
try { text = r.candidates[0].content.parts[0].text; } catch (e) { text = ''; }
let parsed = {};
try { parsed = JSON.parse(text); } catch (e) { parsed = { error: 'model did not return valid JSON', raw: text }; }
// Pass through exact token usage so the platform can account it.
const u = r.usageMetadata || {};
parsed._usage = { prompt: u.promptTokenCount || 0, output: u.candidatesTokenCount || 0, total: u.totalTokenCount || 0 };
return [{ json: parsed }];
